	"testing"
)

func TestPostJobsMissingIDReturns400(t *testing.T) {
	server := newServer()
	body := `{"gpus": 1}`
	req := httptest.NewRequest(http.MethodPost, "/jobs", nil)
	req.Body = http.NoBody // We'll set body manually
	req, _ = http.NewRequest(http.MethodPost, "/jobs", nil)
	// Actually create request with body
	req = httptest.NewRequest(http.MethodPost, "/jobs", nil)
	req.Body = http.NoBody
	// Let's do it properly
	req = httptest.NewRequest(http.MethodPost, "/jobs", nil)
	// Use strings.NewReader
	import "strings"
	req = httptest.NewRequest(http.MethodPost, "/jobs", strings.NewReader(body))

	w := httptest.NewRecorder()
	server.ServeHTTP(w, req)

	if w.Code != http.StatusBadRequest {
		t.Errorf("expected 400, got %d", w.Code)
	}
}

func TestPostJobsSuccess(t *testing.T) {
	server := newServer()
	body := `{"id": "j1", "gpus": 1}`
	req := httptest.NewRequest(http.MethodPost, "/jobs", strings.NewReader(body))
	w := httptest.NewRecorder()
	server.ServeHTTP(w, req)

	if w.Code != http.StatusCreated && w.Code != http.StatusOK {
		t.Errorf("expected 201 or 200, got %d", w.Code)
	}

	var job Job
	if err := json.NewDecoder(w.Body).Decode(&job); err != nil {
		t.Fatalf("failed to decode response: %v", err)
	}
	if job.ID != "j1" {
		t.Errorf("expected id j1, got %s", job.ID)
	}
	if job.GPUs != 1 {
		t.Errorf("expected gpus 1, got %d", job.GPUs)
	}
	if job.Status != "queued" {
		t.Errorf("expected status queued, got %s", job.Status)
	}
}

func TestGetJobsList(t *testing.T) {
	server := newServer()

	// Add a job first
	body := `{"id": "j1", "gpus": 2}`
	req := httptest.NewRequest(http.MethodPost, "/jobs", strings.NewReader(body))
	w := httptest.NewRecorder()
	server.ServeHTTP(w, req)
	if w.Code != http.StatusCreated {
		t.Fatalf("failed to create job: %d", w.Code)
	}

	// Now list jobs
	req = httptest.NewRequest(http.MethodGet, "/jobs", nil)
	w = httptest.NewRecorder()
	server.ServeHTTP(w, req)

	if w.Code != http.StatusOK {
		t.Errorf("expected 200, got %d", w.Code)
	}

	var jobs []Job
	if err := json.NewDecoder(w.Body).Decode(&jobs); err != nil {
		t.Fatalf("failed to decode response: %v", err)
	}
	if len(jobs) != 1 {
		t.Errorf("expected 1 job, got %d", len(jobs))
	}
	if jobs[0].ID != "j1" {
		t.Errorf("expected job id j1, got %s", jobs[0].ID)
	}
}

func TestQueueLengthMetricUpdates(t *testing.T) {
	server := newServer()

	// Initial queue length should be 0
	// We can't directly access metrics, but we can verify via behavior

	// Add first job
	body := `{"id": "j1", "gpus": 1}`
	req := httptest.NewRequest(http.MethodPost, "/jobs", strings.NewReader(body))
	w := httptest.NewRecorder()
	server.ServeHTTP(w, req)
	if w.Code != http.StatusCreated {
		t.Fatalf("failed to create job: %d", w.Code)
	}

	// Add second job
	body = `{"id": "j2", "gpus": 2}`
	req = httptest.NewRequest(http.MethodPost, "/jobs", strings.NewReader(body))
	w = httptest.NewRecorder()
	server.ServeHTTP(w, req)
	if w.Code != http.StatusCreated {
		t.Fatalf("failed to create job: %d", w.Code)
	}

	// List jobs should show 2
	req = httptest.NewRequest(http.MethodGet, "/jobs", nil)
	w = httptest.NewRecorder()
	server.ServeHTTP(w, req)
	if w.Code != http.StatusOK {
		t.Errorf("expected 200, got %d", w.Code)
	}
	var jobs []Job
	json.NewDecoder(w.Body).Decode(&jobs)
	if len(jobs) != 2 {
		t.Errorf("expected 2 jobs, got %d", len(jobs))
	}
}
